package demo.brain;
import org.junit.jupiter.api.Test;
import java.util.*;
import static demo.brain.TwinEngine.*;
import static org.assertj.core.api.Assertions.*;

class TwinEngineTest {
 Snapshot failure(){return inject(initial(42),List.of(new Fault(FaultType.DB_PRIMARY,"db-primary",1,300,0)));}
 @Test void stopRestoresBaselineAfterLimitedRecovery(){var recovered=simulate(failure(),strategies(failure()).get(2)).after();assertThat(recovered.readOnly()).isTrue();var restored=stop(recovered);assertThat(restored.nodes()).isEqualTo(initial(42).nodes());assertThat(restored.writer()).isEqualTo("db-primary");assertThat(restored.time()).isEqualTo(recovered.time());}
 @Test void propagationFramesAreActualTopologicalCalculations(){var frames=propagation(failure());assertThat(node(frames.get(0),"db-primary").availability()).isZero();assertThat(node(frames.get(0),"external-api").availability()).isEqualTo(100);assertThat(frames.get(frames.size()-1)).isEqualTo(failure());}
 @Test void seedsAndSnapshotsAreReproducibleAndImmutable(){var a=initial(42);assertThat(a).isEqualTo(initial(42));assertThat(a).isNotEqualTo(initial(43));assertThat(a.nodes()).hasSize(13);var failed=failure();assertThat(node(a,"db-primary").availability()).isEqualTo(100);assertThat(node(failed,"external-api").availability()).isZero();assertThatThrownBy(()->a.nodes().clear()).isInstanceOf(UnsupportedOperationException.class);}
 @Test void dependencyAndRedundancyUseCapacityRatherThanBlindSpread(){var a=inject(initial(42),List.of(new Fault(FaultType.SERVER_DOWN,"web-1",1,300,0)));assertThat(node(a,"external-api").availability()).isEqualTo(100);var b=inject(a,List.of(new Fault(FaultType.SERVER_DOWN,"web-2",1,300,0)));assertThat(node(b,"external-api").availability()).isZero();}
 @Test void everyFaultChangesActualMetrics(){for(var type:FaultType.values()){String id=switch(type){case DB_PRIMARY,DB_CONNECTION->"db-primary";case REDIS_FAILURE->"redis";case QUEUE_FAILURE->"mq";default->"app-1";};var a=initial(17);var b=inject(a,List.of(new Fault(type,id,1,300,0)));assertThat(node(b,id)).as(type.name()).isNotEqualTo(node(a,id));}}
 @Test void expiryUsesVirtualTimeAndStopRestores(){var a=failure();assertThat(node(advance(a,299),"db-primary").availability()).isZero();assertThat(node(advance(a,300),"db-primary").availability()).isEqualTo(100);assertThat(stop(a).nodes()).isEqualTo(initial(42).nodes());}
 @Test void primaryRestartCanFailAndHealthyReplicaCanSucceed(){var a=failure();var plans=strategies(a);var restart=simulate(a,plans.get(0));var promote=simulate(a,plans.get(1));var protect=simulate(a,plans.get(2));assertThat(restart.outcome()).isEqualTo("FAILED");assertThat(promote.outcome()).isEqualTo("SUCCESS");assertThat(promote.after().writer()).isEqualTo("db-replica");assertThat(protect.outcome()).isEqualTo("PARTIAL");assertThat(protect.availability()).isEqualTo(70);assertThat(a).isEqualTo(failure());assertThat(simulate(a,plans.get(1))).isEqualTo(promote);}
 @Test void compoundReplicaFailureNeverReportsSuccessfulPromotion(){var a=inject(failure(),List.of(new Fault(FaultType.SERVER_DOWN,"db-replica",1,300,0)));var result=simulate(a,strategies(a).get(1));assertThat(result.outcome()).isEqualTo("FAILED");assertThat(result.steps()).anyMatch(st->st.action().equals("PROMOTE_REPLICA")&&!st.applied());assertThat(result.after().writer()).isEqualTo("db-primary");}
 @Test void lagAndMissingFencingPreventFailover(){var a=inject(failure(),List.of(new Fault(FaultType.NETWORK_LATENCY,"db-replica",.5,300,0)));assertThat(simulate(a,strategies(a).get(1)).outcome()).isEqualTo("FAILED");var p=strategies(failure()).get(1);var withoutFence=new Strategy(p.id(),p.name(),p.goal(),p.preconditions(),p.expectedEffect(),p.risk(),p.consistency(),p.rollback(),p.actions().subList(1,p.actions().size()));assertThat(simulate(failure(),withoutFence).after().writer()).isEqualTo("db-primary");}
 @Test void recoveryDoesNotGainCreditFromNaturalExpiry(){var a=inject(initial(42),List.of(new Fault(FaultType.DB_PRIMARY,"db-primary",1,10,0)));var r=simulate(a,strategies(a).get(0));assertThat(r.recoverySeconds()).isGreaterThan(10);assertThat(r.outcome()).isEqualTo("FAILED");}
 @Test void invalidTargetsTypesAndNonfiniteIntensityAreRejected(){assertThatThrownBy(()->inject(initial(42),List.of(new Fault(FaultType.DB_PRIMARY,"web-1",1,300,0)))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->inject(initial(42),List.of(new Fault(FaultType.SERVER_DOWN,"app-1",Double.NaN,300,0)))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->ActionType.valueOf("SHELL")).isInstanceOf(IllegalArgumentException.class);var p=strategies(failure()).get(0);assertThatThrownBy(()->validate(new Strategy(p.id(),p.name(),p.goal(),p.preconditions(),p.expectedEffect(),p.risk(),p.consistency(),p.rollback(),List.of(new Action(ActionType.PROMOTE_REPLICA,"app-1"))),failure())).isInstanceOf(IllegalArgumentException.class);}
 @Test void objectiveWeightsCanChangeRankingsWithoutInventingProbabilities(){var a=failure();var results=strategies(a).stream().map(st->simulate(a,st)).toList();for(var r:results)for(String objective:List.of("SPEED","DATA","STABILITY"))assertThat(score(r,objective)).isBetween(0.0,100.0);assertThat(score(results.get(1),"STABILITY")).isNotEqualTo(score(results.get(1),"SPEED"));}
}
